def P(**kw):
    return kw


def obshchiy_sto(G):
    oil, diag, hod = G.checks.get('замена масла'), G.checks.get('диагностика автомобиля|диагностика авто'), G.checks.get('ремонт ходовой')
    fa = G.med(P(rx=r'^замена воздушного фильтра', ex=r'салон|кондиц', minp=100, maxp=3000))
    fs = G.med(P(rx=r'^замена (салонного|фильтра салона)', minp=100, maxp=3000))
    if not (oil and diag and hod and fa and fs):
        return {'check': None, 'basis': 'tipovoy', 'sources': [], 'kommentariy': 'Не хватает составляющих расчёта (масло, диагностика, фильтры, ходовая).'}
    to = oil + fa + fs + diag
    url = G.url_of('замена масла') or G.url_of('ремонт ходовой')
    src = [{'company': 'Расчёт: типовое ТО', 'url': url, 'price': f'{int(to)} ₽', 'v': to,
            'za_chto': f'замена масла с материалами {int(oil)} ₽ + замена воздушного фильтра {int(fa)} ₽ + замена салонного фильтра {int(fs)} ₽ + компьютерная диагностика {int(diag)} ₽ (медианы по прайсам сервисов)'},
           {'company': 'Расчёт: ремонт ходовой', 'url': G.url_of('ремонт ходовой') or url, 'price': f'{int(hod)} ₽', 'v': hod,
            'za_chto': 'замена двух рычагов и двух амортизаторов (см. строку «Ремонт ходовой»)'}]
    return {'check': int(round((to + hod) / 2, -2)), 'basis': G.basis_of('ремонт ходовой'), 'sources': src, 'status': 'ok',
            'kommentariy': f'Готового «среднего чека» сервисы не публикуют. Число расчётное: среднее двух типовых заказов – ТО ({int(to)} ₽) и ремонт ходовой ({int(hod)} ₽), каждый из медиан прайсов сервисов города на Яндекс Картах.'}


def obshchiy_atelie(G):
    rul, sid = G.checks.get('перетяжка руля'), G.checks.get('перетяжка сидений')
    kpp = G.med(P(rx=r'(перетяжк|перешив)\w* (ручк\w* )?(кпп|короб|рычаг\w* кпп|селектор)', minp=500, maxp=20000))
    if not (rul and sid):
        return {'check': None, 'basis': 'tipovoy', 'sources': [], 'kommentariy': 'Не хватает составляющих расчёта (руль, сиденья).'}
    o1 = rul + (kpp or 0)
    src = [{'company': 'Расчёт: руль + ручка КПП', 'url': G.url_of('перетяжка руля'), 'price': f'{int(o1)} ₽', 'v': o1,
            'za_chto': f'перетяжка руля {int(rul)} ₽' + (f' + перетяжка ручки КПП {int(kpp)} ₽' if kpp else ' (цены ручки КПП не найдено)') + ' (медианы по прайсам ателье)'},
           {'company': 'Расчёт: два передних сиденья', 'url': G.url_of('перетяжка сидений') or G.url_of('перетяжка руля'), 'price': f'{int(sid)} ₽', 'v': sid,
            'za_chto': 'перетяжка двух передних сидений (см. строку «Перетяжка сидений»)'}]
    return {'check': int(round((o1 + sid) / 2, -2)), 'basis': 'tipovoy', 'sources': src, 'status': 'ok',
            'kommentariy': f'Готового «среднего чека» ателье не публикуют. Число расчётное: среднее двух типовых заказов – руль с ручкой КПП ({int(o1)} ₽) и два передних сиденья ({int(sid)} ₽), из медиан прайсов ателье города.'}


def kuzov_raschet(G):
    rih = G.med(P(rx=r'рихтов', ex=r'диск', minp=500, maxp=30000))
    paint = G.checks.get('покраска автомобиля|покраска авто')
    if not (rih and paint):
        return None
    v = round((rih + paint) * 1.5)
    return {'check': v, 'basis': 'tipovoy', 'sources': [{'company': 'Расчёт: рихтовка + покраска', 'url': G.url_of('покраска автомобиля|покраска авто'), 'price': f'{int(v)} ₽', 'v': v,
            'za_chto': f'(рихтовка элемента {int(rih)} ₽ + покраска детали {int(paint)} ₽) × 1,5 элемента, медианы по прайсам'}], 'status': 'malo',
            'kommentariy': 'Позиций «кузовной ремонт» с ценой почти нет; число расчётное: рихтовка и покраска на 1,5 элемента.'}


def detail_raschet(G):
    pol, ker = G.checks.get('полировка автомобиля|полировка авто'), G.checks.get('покрытие керамикой')
    if not (pol and ker):
        return None
    return {'check': int(ker), 'basis': 'tipovoy', 'sources': [{'company': 'Расчёт: полировка + керамика', 'url': G.url_of('покрытие керамикой'), 'price': f'{int(ker)} ₽', 'v': ker,
            'za_chto': 'керамика с подготовкой-полировкой (см. строку «Керамика»)'}], 'status': 'malo',
            'kommentariy': 'Пакетов «полировка + керамика» одной строкой в прайсах почти нет; взята строка «Керамика» (керамика + полировка).'}


